请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-062

=== 用户原始指令 (query.txt) ===
做个免打扰卡片呗，背景有图文字铺在上面，红色提醒别碰手机，点一下跳进去开免打扰，日历里会议也标出来

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "做个免打扰卡片呗，背景有图文字铺在上面，红色提醒别碰手机，点一下跳进去开免打扰，日历里会议也标出来",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModel": {
    "value": {
      "focus": {
        "title": "免打扰",
        "modeText": "专注会议中",
        "alertText": "别碰手机",
        "reminder": "已屏蔽来电和横幅提醒",
        "actionText": "开启免打扰",
        "progress": {
          "value": 45,
          "total": 60,
          "label": "45分钟"
        }
      },
      "calendar": {
        "items": [
          {
            "entityName": "calendar",
            "entityId": "mock-focus-meeting-062",
            "title": "项目同步会",
            "dtStart": "15:00",
            "dtEnd": "15:45",
            "eventLocation": "3F 会议室"
          }
        ]
      },
      "assets": {
        "focusIcon": "resources/base/media/icon_focus.png",
        "meetingIcon": "resources/base/media/icon_meeting.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "focus_icon",
      "src": "resources/base/media/icon_focus.png",
      "use": "focus mode icon",
      "description": "专注模式图标，可作为免打扰卡片的背景视觉锚点。",
      "bindTo": "/assets/focusIcon",
      "static": true
    },
    {
      "assetRef": "meeting_icon",
      "src": "resources/base/media/icon_meeting.png",
      "use": "calendar meeting icon",
      "description": "会议图标，可用于标识日历中的会议日程。",
      "bindTo": "/assets/meetingIcon",
      "static": true
    }
  ]
}

